document.querySelectorAll('shopify-context[type="product"]').forEach(ctx => {
const handle = ctx.getAttribute('handle');
const data = productCatalog[handle];
if (!data) return;
const observer = new MutationObserver(() => {
if (ctx.textContent.includes('GraphQL Client:') || ctx.textContent.includes('shopify-context:')) {
ctx.innerHTML = renderFallbackCard(handle, data);
}
});
observer.observe(ctx, { childList: true, subtree: true });
});
let cart = [];
