function openProductModal(handle) {
const product = productCatalog[handle];
if (!product) return;
const modal = document.getElementById('product-modal');
if (!modal) return;
document.getElementById('modal-product-img').src = product.image;
document.getElementById('modal-product-title').textContent = product.title;
document.getElementById('modal-product-price').textContent = `$${product.price.toFixed(2)} USD`;
document.getElementById('modal-product-compare').textContent = `$${product.comparePrice.toFixed(2)} USD`;
document.getElementById('modal-product-savings').textContent = product.savings;
document.getElementById('modal-product-desc').textContent = product.description;
const featuresEl = document.getElementById('modal-product-features');
if (featuresEl && product.features) {
featuresEl.innerHTML = product.features.map(f => `
<li class="product-card__features-item">
<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M20 6L9 17l-5-5"/></svg>
<span>${f}</span>
</li>
`).join('');
}
const addBtn = document.getElementById('modal-add-btn');
addBtn.onclick = () => {
quickAddToCart(handle, product.title, product.price, product.image);
modal.close();
};
const buyBtn = document.getElementById('modal-buy-btn');
buyBtn.onclick = () => {
quickAddToCart(handle, product.title, product.price, product.image);
modal.close();
proceedToCheckout();
};
modal.showModal();
}
function toggleFaq(btn) {
const item = btn.parentElement;
const isOpen = item.classList.contains('is-open');
document.querySelectorAll('.faq-item').forEach(el => el.classList.remove('is-open'));
if (!isOpen) {
item.classList.add('is-open');
}
}
const mobileBar = document.getElementById('mobile-sticky-bar');
window.addEventListener('scroll', () => {
if (!mobileBar) return;
if (window.scrollY > 400) {
mobileBar.classList.add('is-visible');
} else {
mobileBar.classList.remove('is-visible');
}
}, { passive: true });
let toastTimeout;
function showToast(message) {
const toast = document.getElementById('toast-notification');
const toastText = document.getElementById('toast-text');
if (!toast || !toastText) return;
toastText.textContent = message;
toast.classList.add('is-visible');
clearTimeout(toastTimeout);
toastTimeout = setTimeout(() => {
toast.classList.remove('is-visible');
}, 3500);
}
